import sys

def solve():
    s = sys.stdin.read().strip()
    n = len(s)

    diff = int(s, 16)

    if diff == 0:
        print("NO")
        return

    digits = [int(c, 16) for c in s]
    total_sum = sum(digits)

    if total_sum % 2 != 0:
        print("NO")
        return

    target_a = total_sum // 2

    def find_smallest(target, count):
        if count == 0:
            return "" if target == 0 else None

        current_digit = 0
        while True:
            remaining_count = count - 1
            remaining_target = target - current_digit

            if remaining_target < 0:
                break

            max_possible = 15 * remaining_count
            min_possible = 0 * remaining_count

            if min_possible <= remaining_target <= max_possible:
                used_count = digits.count(current_digit)
                if used_count > 0:
                    temp_digits = digits.copy()
                    temp_digits.remove(current_digit)
                    res = find_smallest(remaining_target, remaining_count)
                    if res is not None:
                        return str(current_digit) + res
            current_digit += 1

        return None

    result = find_smallest(target_a, n)

    if result is None:
        print("NO")
    else:
        print(result)

if __name__ == "__main__":
    solve()
